    spec(6, "사내변호사의 사직", "사내변호사는 위법행위 시정을 위하여 의견을 개진하였음에도 아무런 조치가 없으면 사직할 수 있다.", "사내변호사는 회사의 위법행위에 관하여 의견을 개진한 뒤 아무런 조치가 없어도 사직할 수 없다.", "변호사법 제2조, 제24조", "사직 가능성"),

    spec(7, "법무법인 유한 설립요건", "법무법인 유한은 7명 이상의 변호사로 구성하고 그중 2명 이상은 통산하여 10년 이상의 법조경력이 있어야 한다.", "법무법인 유한은 5명 이상의 변호사만 있으면 법조경력 요건 없이 설립할 수 있다.", "변호사법 제58조의6 제1항", "설립 인원과 경력"),
    spec(7, "법무조합 손해배상책임", "법무조합의 수임사건 손해배상책임은 담당변호사와 지휘·감독 구성원 및 조합재산 책임 구조에 따라 판단된다.", "법무조합은 수임사건 손해에 관하여 언제나 담당변호사와 동일한 내용의 연대책임을 진다.", "변호사법 제58조의25", "법무조합 책임구조"),
    spec(7, "법무법인과 법무조합 해산", "법무법인은 구성원 전원의 동의가 있을 때 해산하고, 법무조합은 규약에 다른 정함이 없으면 구성원 과반수의 동의로 해산한다.", "법무법인과 법무조합은 모두 구성원 전원의 동의가 있어야만 해산할 수 있다.", "변호사법 제56조, 제58조의29", "해산 동의요건"),
    spec(7, "법률전문단체의 당사자능력", "법무법인, 법무법인 유한, 법무조합은 모두 소송의 당사자능력이 인정된다.", "법무조합은 법인이 아니므로 소송의 당사자능력이 인정되지 않는다.", "민사소송법상 당사자능력 관련 판례", "법무조합 당사자능력"),

    spec(8, "법관의 일방 접촉 금지", "법관은 재판업무상 필요한 경우를 제외하고 당사자나 대리인 등 소송관계인을 법정 밖에서 면담하거나 접촉해서는 안 된다.", "법관은 재판의 신속한 진행을 위하여 언제든지 당사자나 대리인을 법정 밖에서 개별 면담할 수 있다.", "법관윤리강령 제4조", "법정 외 접촉"),
    spec(8, "법관의 공개 논평 제한", "법관은 교육·학술 또는 정확한 보도를 위한 경우 등을 제외하고 구체적 사건에 관하여 공개적으로 논평하거나 의견을 표명해서는 안 된다.", "법관은 담당하지 않는 사건이면 구체적 사건에 관하여 공개적으로 의견을 표명할 수 있다.", "법관윤리강령 제5조", "구체적 사건 논평"),
    spec(8, "특별사법경찰관리 지휘", "검사는 특별사법경찰관리에 대하여 법령상 지휘·감독 권한을 가진다.", "수사권 조정 이후에는 특별사법경찰관리에 대한 검사의 지휘·감독권이 인정되지 않는다.", "검사윤리강령 제6조, 형사소송법", "특별사법경찰관리"),
    spec(8, "검사의 이의제기", "검사는 구체적 사건에 관한 상급자의 지휘·감독의 적법성이나 정당성에 이견이 있으면 절차에 따라 이의를 제기할 수 있다.", "검사는 상급자의 지휘·감독에 이견이 있어도 어떠한 절차로도 이의를 제기할 수 없다.", "검사윤리강령 제7조", "상급자 지휘 이견"),

    spec(9, "사무직원과 집행유예", "변호사법상 일정 범죄로 징역형의 집행유예를 선고받고 그 유예기간이 지난 후 2년이 지나지 않은 자는 법률사무소 사무직원으로 채용될 수 없다.", "일정 범죄로 징역형의 집행유예를 선고받았더라도 유예기간만 지나면 곧바로 법률사무소 사무직원으로 채용될 수 있다.", "변호사법 제22조 제2항 제1호", "집행유예 후 2년"),
    spec(9, "사무직원과 선고유예", "변호사법상 일정 범죄로 징역형의 선고유예를 받고 그 유예기간 중에 있는 자는 법률사무소 사무직원으로 채용될 수 없다.", "일정 범죄로 징역형의 선고유예를 받았더라도 형이 확정되지 않았으므로 유예기간 중에도 사무직원으로 채용될 수 있다.", "변호사법 제22조 제2항 제1호", "선고유예 기간"),
    spec(9, "파산선고와 사무직원", "파산선고를 받고 면책이나 복권을 받지 못했다는 사정만으로는 변호사법상 법률사무소 사무직원 채용 결격사유가 되지 않는다.", "파산선고를 받고 면책이나 복권을 받지 못한 자는 변호사법상 법률사무소 사무직원으로 채용될 수 없다.", "변호사법 제22조 제2항", "파산선고"),
    spec(9, "공무원 징계와 사무직원", "공무원으로서 정직 징계처분을 받고 퇴직했다는 사정만으로는 변호사법상 법률사무소 사무직원 채용 결격사유가 되지 않는다.", "공무원으로서 정직 징계처분을 받고 퇴직한 자는 변호사법상 법률사무소 사무직원으로 채용될 수 없다.", "변호사법 제22조 제2항 제2호", "정직과 파면·해임"),

    spec(10, "변리사 등록", "변리사 자격이 있는 변호사가 변리사로서 업무를 하려면 특허청장에게 변리사 등록을 하여야 한다.", "변리사 자격이 있는 변호사는 별도의 변리사 등록 없이 곧바로 변리사 업무를 할 수 있다.", "변리사법", "변리사 등록"),
    spec(10, "변호사의 변리사 자격", "변호사 자격을 가진 사람이 변리사법 시행령상 실무수습을 마치면 변리사의 자격이 있다.", "변호사 자격을 가진 사람은 실무수습을 마치더라도 변리사 자격을 취득할 수 없다.", "변리사법", "실무수습"),
    spec(10, "변리사의 소송대리 범위", "변리사의 소송대리는 변리사법과 특허 관련 절차가 정한 범위에서만 인정되며, 특허 등 침해를 원인으로 한 민사소송 전부를 단독 대리할 수 있다는 뜻은 아니다.", "변리사는 특허 등 침해를 청구원인으로 하는 침해금지청구와 손해배상청구 민사소송을 단독으로 대리할 수 있다.", "변호사법 제3조, 관련 판례", "민사소송 단독대리"),
    spec(10, "법무법인의 특허대리업무", "법무법인은 변리사 자격을 가진 구성원 변호사를 담당변호사로 지정하여 법무법인 명의로 상표출원 등 특허대리업무를 수행할 수 있다.", "법무법인은 구성원 변호사가 변리사 자격을 가지고 있더라도 법무법인 명의로 특허대리업무를 수행할 수 없다.", "변호사법 제3조, 관련 판례", "법무법인 명의 업무"),

    spec(11, "비밀유지와 의뢰인 동의", "변호사는 의뢰인의 동의를 얻으면 직무상 작성한 사건진행·소송전략 관련 자료를 외부에 공개할 수 있다.", "변호사는 의뢰인의 명시적 동의를 얻어도 직무상 작성한 사건진행·소송전략 자료를 외부에 공개할 수 없다.", "변호사법 제26조, 변호사윤리장전 제18조", "의뢰인 동의"),
    spec(11, "자기방어를 위한 비밀 공개", "변호사는 자신을 방어하기 위하여 필요한 경우 직무수행 중 알게 된 의뢰인의 비밀을 최소한의 범위에서 공개할 수 있다.", "변호사는 자신이 형사고소를 당해 방어가 필요한 경우에도 의뢰인의 비밀을 전혀 공개할 수 없다.", "변호사법 제26조", "자기방어"),
    spec(11, "법률의견서와 증언거부", "변호사가 작성한 법률의견서가 의뢰인의 비밀을 포함한다는 점을 소명하면 그 의견서에 관한 증언을 거부할 수 있다.", "변호사가 작성한 법률의견서는 문서로 존재하므로 의뢰인의 비밀을 포함하더라도 증언거부의 대상이 될 수 없다.", "변호사법 제26조, 형사소송법상 증언거부", "법률의견서"),
    spec(11, "퇴직 후 비밀 이용 금지", "법무법인 소속 변호사가 같은 법무법인에서 알게 된 의뢰인의 직무상 비밀은 퇴직 후에도 이용할 수 없다.", "법무법인 소속 변호사는 퇴직 후에는 같은 법무법인에서 알게 된 의뢰인의 직무상 비밀을 이용할 수 있다.", "변호사법 제26조, 제57조", "퇴직 후 이용"),

    spec(12, "사임 후 비밀유지", "변호사가 의뢰인의 범죄행위 요구에 협조를 중단하고 사임하더라도 의뢰인의 비밀에 대한 비밀유지의무는 원칙적으로 계속된다.", "변호사가 의뢰인의 범죄행위 요구 때문에 사임하면 의뢰인의 비밀에 대한 비밀유지의무는 곧바로 해제된다.", "변호사법 제26조", "사임과 비밀유지"),
    spec(12, "압수거부와 공익", "변호사가 보관하는 의뢰인의 비밀 관련 물건이라도 중대한 공익상 필요가 있으면 압수거부권이 제한될 수 있다.", "변호사가 보관하는 의뢰인의 비밀 관련 물건은 중대한 공익상 필요가 있어도 언제나 압수를 거부할 수 있다.", "변호사법 제26조, 형사소송법", "압수거부 제한"),
    spec(12, "증언거부와 출석의무", "변호사가 직무상 알게 된 의뢰인의 비밀과 관련하여 증인으로 소환되면 출석의무와 선서의무는 원칙적으로 부담하되, 비밀에 관한 증언을 거부할 수 있다.", "변호사가 의뢰인의 비밀과 관련하여 증인으로 소환되면 법정 출석 자체와 증인 선서를 모두 거부할 수 있다.", "변호사법 제26조, 형사소송법", "출석과 증언거부"),
    spec(12, "공익신고와 비밀유지", "변호사가 공익신고자 보호법상 공익신고자에 해당하면 그 법에 따른 신고는 비밀유지의무 위반으로 보지 않는다.", "변호사가 공익신고자 보호법상 공익신고자에 해당하더라도 직무상 알게 된 비밀을 신고하면 언제나 비밀유지의무 위반이다.", "변호사법 제26조, 공익신고자 보호법", "법률상 예외"),

    spec(13, "제3자의 비밀", "변호사는 직무상 알게 된 비밀이라면 그것이 자기 의뢰인의 비밀이 아니더라도 함부로 누설해서는 안 된다.", "변호사법상 비밀유지의무는 자기 의뢰인의 비밀에만 미치므로 직무상 알게 된 제3자의 비밀은 자유롭게 누설할 수 있다.", "변호사법 제26조", "제3자 비밀"),
    spec(13, "상대방 관련 비밀 누설", "변호사가 직무상 알게 된 상대방 관련 비밀을 현재 의뢰인에게 알려 주는 것도 비밀유지의무 위반이 될 수 있다.", "변호사는 현재 의뢰인의 이익을 위한다면 직무상 알게 된 상대방 관련 비밀을 자유롭게 알려 줄 수 있다.", "변호사법 제26조, 변호사윤리장전 제18조", "현재 의뢰인 이익"),
    spec(13, "이혼사건과 위자료청구 사건", "상간자에 대한 위자료청구 사건과 그 배우자의 이혼 사건은 구체적 사정에 따라 이해충돌 여부를 판단하며 당연히 수임금지되는 것은 아니다.", "상간자에 대한 위자료청구 사건을 수임 중인 법무법인은 그 배우자의 이혼 사건을 언제나 수임할 수 없다.", "변호사법 제31조, 변호사윤리장전 제22조", "이익충돌 단정"),
    spec(13, "법무법인 탈퇴 후 수임", "법무법인 탈퇴 후 수임제한은 재직 중 접한 모든 상담 사건에 당연히 미치는 것이 아니라 비밀유지와 이해충돌 기준에 따라 판단된다.", "변호사는 법무법인 소속 기간 중 상담이 있었던 사건이면 탈퇴 후에도 언제나 수임할 수 없다.", "변호사법 제31조, 변호사윤리장전 제22조", "탈퇴 후 수임"),

    spec(14, "선임서 지방변호사회 경유", "변호사는 법률사건이나 법률사무에 관한 변호인선임서 또는 위임장을 공공기관에 제출할 때 사전에 소속 지방변호사회를 경유하여야 한다.", "변호사는 변호인선임서나 위임장을 공공기관에 제출할 때 소속 지방변호사회를 경유할 필요가 없다.", "변호사법 제29조", "지방변호사회 경유"),
    spec(14, "내사사건 변호인선임서", "내사 중인 형사사건의 피의자를 변호하는 경우에도 변호인선임서 제출 의무가 문제된다.", "내사 중인 형사사건의 피의자를 변호하는 경우에는 수사기관에 변호인선임서를 제출할 필요가 없다.", "변호사법 제29조의2", "내사사건"),
    spec(14, "수임장부", "변호사는 수임에 관한 장부를 작성하고 보관하여야 한다.", "변호사는 수임 사건의 장부를 작성할 의무가 없다.", "변호사법 제28조", "수임장부"),
    spec(14, "수임건수와 수임액 보고", "변호사는 매년 1월 말까지 전년도에 처리한 수임사건의 건수와 수임액을 소속 지방변호사회에 보고하여야 한다.", "변호사는 수임사건의 건수와 수임액을 대한변호사협회에만 보고하면 되고 소속 지방변호사회에는 보고하지 않는다.", "변호사법 제28조의2", "보고기관"),

    spec(15, "위원회 활동과 공익활동", "지방변호사회나 대한변호사협회의 위원회에서 위원으로서 활동하는 것은 공익활동으로 인정될 수 있다.", "지방변호사회나 대한변호사협회의 위원회 활동은 변호사 개인의 공익활동으로 인정될 수 없다.", "공익활동 등에 관한 규정 제2조", "위원회 활동"),
    spec(15, "공익활동 감면", "지방변호사회는 일정한 사유가 있는 변호사의 공익활동 의무를 감면할 수 있으나, 법조경력 2년 미만이라는 사유만으로 연간 20시간까지 하향 조정한다고 표현할 수는 없다.", "지방변호사회는 법조경력 2년 미만 변호사의 공익활동 의무를 연간 20시간까지 하향 조정할 수 있다.", "변호사법 제27조, 공익활동 등에 관한 규정 제3조", "20시간 하향 조정"),
    spec(15, "공익활동 결과 보고", "변호사는 매년 2월 말까지 전년도 공익활동 결과를 소속 지방변호사회에 보고하여야 한다.", "변호사는 공익활동 결과를 매년 1월 말까지 대한변호사협회에 직접 보고하여야 한다.", "공익활동 등에 관한 규정 제5조", "보고기한"),
    spec(15, "법무법인 공익활동 배분", "법무법인 등이 공익활동을 수행한 변호사에게 배분한 시간은 그 수행 변호사 자신의 공익활동 시간으로 인정될 수 있다.", "법무법인 등이 수행한 공익활동 시간은 수행 변호사 개인의 공익활동 시간으로 인정될 수 없다.", "공익활동 등에 관한 규정 제3조", "시간 배분"),

    spec(16, "거짓 광고와 형사처벌", "변호사가 업무에 관하여 거짓된 내용을 표시하는 광고를 하는 행위는 변호사법상 형사처벌 대상이 된다.", "변호사가 업무에 관하여 거짓된 내용을 표시하는 광고를 하더라도 징계만 문제되고 형사처벌 대상은 아니다.", "변호사법 제23조 제2항 제1호, 제113조", "거짓 광고"),
    spec(16, "과장 광고", "객관적 사실을 과장하여 소비자를 오도하는 광고는 금지되지만, 변호사법상 형사처벌 조항은 거짓 광고 등 일부 광고 위반에 한정된다.", "객관적 사실을 과장하여 소비자를 오도하는 광고는 거짓 광고와 동일하게 언제나 변호사법상 형사처벌 대상이다.", "변호사법 제23조, 제113조", "금지 광고와 형사처벌"),
    spec(16, "비교 광고", "다른 변호사를 비방하거나 자신의 입장에서 비교하는 광고는 금지되지만, 그 광고가 곧바로 변호사법상 형사처벌 대상이 되는 것은 아니다.", "다른 변호사를 비방하거나 자신의 입장에서 비교하는 광고는 언제나 변호사법상 형사처벌 대상이다.", "변호사법 제23조, 변호사 광고에 관한 규정 제4조", "비교 광고"),
    spec(16, "품위훼손 광고", "부정한 방법을 제시하는 등 변호사의 품위를 훼손할 우려가 있는 광고는 금지되지만, 그 자체가 언제나 변호사법상 형사처벌 대상인 것은 아니다.", "부정한 방법을 제시하는 등 변호사의 품위를 훼손할 우려가 있는 광고는 언제나 변호사법상 형사처벌 대상이다.", "변호사법 제23조, 변호사 광고에 관한 규정 제4조", "품위훼손 광고"),

    spec(17, "성공보수 선수령", "민사사건에서 패소 시 반환을 조건으로 성공보수를 미리 수령하는 약정은 허용될 수 있다.", "민사사건에서 성공보수는 사건 종료 전에는 어떠한 조건으로도 미리 수령할 수 없다.", "민법 제686조, 관련 판례", "성공보수 선수령"),
    spec(17, "보관금과 착수금 상계", "의뢰인이 착수금을 지급하지 않은 경우 변호사는 의뢰인을 위하여 보관 중인 금전채권과 착수금 채권을 대등액에서 상계할 수 있다.", "변호사는 의뢰인을 위하여 보관 중인 금전과 자신의 착수금 채권을 어떠한 경우에도 상계할 수 없다.", "민법 제492조, 제686조", "보관금 상계"),
    spec(17, "성공보수 소멸시효", "제1심 전부승소에 따른 성공보수청구권의 소멸시효는 특별한 사정이 없으면 제1심 판결을 송달받은 때부터 진행한다.", "제1심 성공보수청구권의 소멸시효는 사건을 수임한 날부터 진행한다.", "민법 제686조, 관련 판례", "소멸시효 기산점"),
    spec(17, "화해권고결정과 성공보수", "성공보수 약정에서 일부 승소가 보수 발생 사유로 정해진 경우 화해권고결정 확정도 그 약정의 일부 승소에 해당할 수 있다.", "성공보수 약정에서 일부 승소가 보수 발생 사유로 정해져 있어도 화해권고결정 확정은 언제나 일부 승소에 해당하지 않는다.", "민법 제686조, 관련 판례", "화해권고결정"),

    spec(18, "추가보수 요구 제한", "변호사는 정당한 사유 없이 약정된 성공보수 외에 추가보수를 요구할 수 없다.", "변호사는 사건이 어려웠다는 이유만으로 약정된 성공보수 외의 추가보수를 자유롭게 요구할 수 있다.", "민법 제686조, 변호사윤리장전 제31조", "추가보수"),
    spec(18, "민사 성공보수 약정", "민사사건에서 착수금을 받지 않고 승소 판결금의 일정 비율을 성공보수로 받기로 하는 약정이 그 이유만으로 당연히 무효가 되는 것은 아니다.", "민사사건에서 착수금을 전혀 받지 않고 승소 판결금의 절반을 성공보수로 받기로 하는 약정은 언제나 무효이다.", "민법 제103조, 제686조", "당연무효"),
    spec(18, "부당과다 보수 감액", "약정 보수액이 부당하게 과다하여 신의성실의 원칙이나 형평의 원칙에 반하는 특별한 사정이 있으면 상당한 범위의 보수만 청구할 수 있다.", "변호사 보수약정은 사적 자치에 따른 것이므로 약정액이 부당하게 과다하더라도 감액될 수 없다.", "민법 제103조, 제686조, 관련 판례", "신의칙 감액"),
    spec(18, "보수분쟁 해결", "의뢰인이 보수를 지급하지 않으면 변호사는 보수금청구의 소를 제기하거나 소속 지방변호사회에 분쟁조정을 신청할 수 있다.", "의뢰인이 보수를 지급하지 않더라도 변호사는 소송이나 지방변호사회 분쟁조정을 이용할 수 없다.", "민법 제686조, 변호사 보수 관련 규정", "보수분쟁"),

    spec(19, "최고 표현 광고", "변호사 광고에서 최고라는 표현은 객관적 선정 사실이 있더라도 소비자를 오도할 우려가 있어 제한될 수 있다.", "언론사가 선정한 사실이 있으면 변호사는 광고에 최고라는 표현을 언제나 사용할 수 있다.", "변호사법 제23조, 변호사 광고에 관한 규정 제4조", "최고 표현"),
    spec(19, "전문 표현", "전문분야 등록이 없더라도 구체적인 경력이나 업무 경험을 설명하는 방식의 전문성 표시는 전부 금지되는 것은 아니다.", "대한변호사협회 전문분야 등록이 없으면 변호사는 어떤 방식으로도 특정 분야의 업무 경험이나 전문성을 표시할 수 없다.", "변호사 광고에 관한 규정 제4조", "전문 표현"),
    spec(19, "명함 교부와 방문상담", "공익 목적으로 방문하여 의뢰 권유 없이 무료 법률상담을 제공하면서 명함을 교부하는 행위가 항상 금지되는 것은 아니다.", "변호사가 자신과 아무 관계가 없던 사람에게 명함을 교부하면 의뢰 권유가 없더라도 언제나 금지된다.", "변호사법 제23조, 변호사 광고에 관한 규정 제5조", "명함 교부"),
    spec(19, "의뢰 권유 없는 법률상담", "피해자나 유족에게 사건 의뢰를 권유하지 않고 공익 목적으로 법률상담을 제공하는 행위는 허용될 수 있다.", "변호사는 피해자나 유족에게 사건 의뢰를 권유하지 않더라도 사건 현장 관련 장소를 방문하여 법률상담을 제공할 수 없다.", "변호사 광고에 관한 규정 제5조", "방문상담"),

    spec(20, "변호사의 진실의무", "변호사인 변호인에게는 변호사법과 변호사윤리장전에 따른 진실의무가 인정된다.", "변호사인 변호인에게는 변호사법상 진실의무가 인정되지 않는다.", "변호사법 제1조, 제24조, 변호사윤리장전 제14조", "진실의무 인정"),
    spec(20, "소송법상 명문규정", "민사소송법과 형사소송법이 변호사의 진실의무를 명시적으로 규정하고 있다고 볼 수는 없다.", "민사소송법과 형사소송법은 변호사의 진실의무를 명시적으로 규정하고 있다.", "변호사법 제24조, 관련 판례", "명문규정"),
    spec(20, "진술거부권 조언", "변호인이 신체구속을 당한 피의자에게 진술거부권 행사를 권고하는 것은 변호사의 진실의무에 위배되지 않는다.", "변호인이 신체구속을 당한 피의자에게 진술거부권 행사를 권고하면 변호사의 진실의무에 위배된다.", "헌법 제12조, 변호사법 제24조", "진술거부권"),
    spec(20, "불리한 증거 제출의무", "형사소송절차에서 변호사의 진실의무는 실체적 진실발견을 적극적으로 방해하지 않을 소극적 의무이므로 피고인에게 불리한 증거를 제출할 의무까지 포함하지 않는다.", "형사소송절차에서 변호사는 진실의무 때문에 피고인에게 불리한 증거를 법원에 제출할 의무가 있다.", "변호사법 제24조, 관련 판례", "불리한 증거"),

    spec(21, "개업 등록", "변호사로서 개업하려면 가입하려는 지방변호사회를 거쳐 대한변호사협회에 등록하여야 한다.", "변호사로서 개업하려면 소속 지방변호사회에만 신고하면 되고 대한변호사협회 등록은 필요하지 않다.", "변호사법 제7조", "대한변협 등록"),
    spec(21, "등록신청 의견서", "지방변호사회는 변호사 등록신청을 받으면 해당 변호사의 자격 유무에 관한 의견서를 첨부할 수 있다.", "지방변호사회는 변호사 등록신청을 받아도 자격 유무에 관한 의견서를 첨부할 수 없다.", "변호사법 제8조", "의견서"),
    spec(21, "소속 변경등록", "변호사가 지방변호사회 소속을 변경하려면 새로 가입하려는 지방변호사회를 거쳐 대한변호사협회에 소속 변경등록을 신청하여야 한다.", "변호사가 지방변호사회 소속을 변경하려면 종전 소속 지방변호사회를 거쳐 대한변호사협회에 소속 변경등록을 신청하여야 한다.", "변호사법 제12조", "종전 소속과 새 소속"),
    spec(21, "개업과 사무소 이전 신고", "변호사가 개업하거나 법률사무소를 이전한 경우에는 지체 없이 소속 지방변호사회와 대한변호사협회에 신고하여야 한다.", "변호사가 법률사무소를 이전한 경우에는 대한변호사협회에만 신고하면 된다.", "변호사법 제21조", "신고기관"),

    spec(22, "홈페이지 원고 모집 광고", "법무법인의 인터넷 홈페이지에 특정 사건 피해자들을 모집하기 위한 광고를 게시하는 것은 허용될 수 있다.", "법무법인은 인터넷 홈페이지에 특정 사건 피해자들을 모집하기 위한 광고를 게시할 수 없다.", "변호사법 제23조, 변호사 광고에 관한 규정 제5조", "홈페이지 광고"),
    spec(22, "버스 외부 광고", "버스 외부에 특정 소송의 원고를 모집한다는 취지의 변호사 광고를 하는 것은 허용되지 않는다.", "버스 외부에 특정 소송의 원고를 모집한다는 취지의 변호사 광고를 하는 것은 허용된다.", "변호사 광고에 관한 규정 제5조", "옥외 대중교통 광고"),
    spec(22, "어깨띠 광고", "피해자들이 집회하는 곳에 변호사 표시 어깨띠를 하고 찾아가 자신을 광고하는 행위는 허용되지 않는다.", "피해자들이 집회하는 곳에서 변호사 표시 어깨띠를 착용하고 자신을 광고하는 행위는 허용된다.", "변호사 광고에 관한 규정 제5조", "집회장소 광고"),
    spec(22, "불특정 다수 SNS 광고", "특정 투자 관련 사이트의 불특정 다수 회원에게 자신을 광고하는 SNS 메시지를 발송하는 것은 허용되지 않는다.", "불특정 다수의 사이트 회원에게 자신을 광고하는 SNS 메시지를 발송하는 것은 허용된다.", "변호사 광고에 관한 규정 제5조", "SNS 발송"),

    spec(23, "수임제한 해제 광고", "변호사법상 수임제한이 해제되었다는 내용을 사건수임 광고로 표시하는 것은 허용되지 않는다.", "변호사법상 수임제한이 해제되었다는 사실은 사건수임 광고에 자유롭게 표시할 수 있다.", "변호사 광고에 관한 규정 제4조", "수임제한 해제"),
    spec(23, "승소율 광고", "승소율을 기재하는 변호사 광고는 소비자를 오도하거나 부당한 기대를 갖게 할 우려가 있어 허용되지 않는다.", "변호사 광고에서 승소율을 기재하는 것은 객관적 통계만 있으면 언제나 허용된다.", "변호사 광고에 관한 규정 제4조", "승소율"),
    spec(23, "의뢰인 사례 광고", "널리 일반에 알려진 의뢰인 사건은 일정한 범위에서 의뢰인 동의 없이 광고에 사용할 수 있다.", "널리 일반에 알려진 의뢰인 사건도 의뢰인의 동의가 없으면 어떠한 경우에도 광고에 사용할 수 없다.", "변호사 광고에 관한 규정 제4조", "널리 알려진 사건"),
    spec(23, "전문법무법인 표시", "구성원 일부의 전문분야 등록만으로 법무법인 자체를 대한변호사협회 등록 전문법무법인이라고 광고할 수는 없다.", "법무법인 구성원 중 한 명이 전문분야 등록을 한 상태이면 법무법인 자체를 대한변호사협회 등록 전문법무법인이라고 광고할 수 있다.", "변호사 광고에 관한 규정 제4조", "전문법무법인"),

    spec(24, "비변호사와 동업 금지", "변호사와 변호사가 아닌 자의 동업과 보수 분배는 변호사법과 변호사윤리장전에서 금지된다.", "변호사와 변호사가 아닌 자의 동업은 변호사윤리장전에서만 금지되고 변호사법에서는 금지되지 않는다.", "변호사법 제34조, 변호사윤리장전 제34조", "동업금지"),
    spec(24, "비변호사의 변호사 고용", "변호사가 아닌 자가 변호사를 고용하여 법률사무소를 개설·운영하는 행위는 변호사법상 금지된다.", "변호사가 아닌 자가 변호사를 고용하여 법률사무소를 운영하는 것은 변호사 명의가 있으면 허용된다.", "변호사법 제34조 제4항", "비변호사 고용"),
    spec(24, "보수분배 형사처벌", "변호사법상 변호사와 변호사가 아닌 자의 위법한 보수 분배 금지에는 형사처벌 조항이 연결된다.", "변호사법상 변호사와 변호사가 아닌 자의 보수 분배 금지에는 형사처벌 조항이 없다.", "변호사법 제34조, 제109조", "형사처벌 조항"),
    spec(24, "비변호사 보수약정", "변호사가 아닌 자가 변호사가 아니면 할 수 없는 업무에 관하여 보수를 받기로 한 약정은 무효이다.", "변호사가 아닌 자가 변호사가 아니면 할 수 없는 업무에 관하여 보수를 받기로 한 약정도 사적 자치에 따라 유효하다.", "변호사법 제34조, 민법 제103조", "보수약정 무효"),

    spec(25, "수임거절 금지", "변호사는 의뢰인이나 사건이 사회 일반으로부터 비난받는다는 이유만으로 수임을 거절하지 않는다.", "변호사는 의뢰인이나 사건이 사회 일반으로부터 비난받는다는 이유만으로 수임을 거절할 수 있다.", "변호사윤리장전 제20조", "사회적 비난"),
    spec(25, "승소가능성 장담 금지", "변호사는 의뢰인이 기대하는 결과를 얻을 가능성이 없거나 희박한 사건을 가능성이 높은 것으로 설명하거나 장담하지 않는다.", "변호사는 의뢰인의 수임 결정을 돕기 위해 희박한 사건도 가능성이 높은 것으로 설명할 수 있다.", "변호사윤리장전 제19조", "가능성 장담"),
    spec(25, "국선 등 지정사건과 이해상반", "국선변호 등으로 지정된 사건이라도 이미 수임한 사건과 이해관계가 상반되면 수임제한 기준에 따라 처리하여야 한다.", "국선변호 등으로 지정된 사건은 이미 수임한 사건과 이해관계가 상반되어도 반드시 처리하여야 한다.", "변호사윤리장전 제22조", "국선과 이해상반"),
    spec(25, "부당한 의뢰인 요구", "변호사는 의뢰인의 요구가 변호사의 품위를 손상시키거나 의뢰인의 이익에 배치된다고 인정하면 그 이유를 설명하고 따르지 않을 수 있다.", "변호사는 의뢰인의 요구가 품위를 손상시키더라도 의뢰인이 원하면 반드시 따라야 한다.", "변호사윤리장전 제19조", "부당한 요구"),

    spec(26, "알선업자 이용 금지", "변호사는 사건 알선을 업으로 하는 자로부터 사건 소개를 받거나 그러한 자에게 자기 명의를 이용하게 해서는 안 된다.", "변호사는 사건 알선을 업으로 하는 자가 소개료를 받지 않는다면 그로부터 사건 소개를 받을 수 있다.", "변호사법 제34조", "알선업자"),
    spec(26, "소송사무 종료 시점", "민사소송 수임사무는 당해 심급 판결 선고만으로 당연히 종료한다고 볼 수 없고, 위임계약 내용과 후속 조치 의무를 함께 보아야 한다.", "민사소송에서 변호사의 당해 심급 수임사무는 판결 선고와 동시에 언제나 종료한다.", "민법 제681조, 관련 판례", "판결 선고"),
    spec(26, "불리한 시기 해지", "위임계약을 불리한 시기에 해지한 경우 손해배상 범위는 적당한 시기에 해지되었더라면 입지 않았을 손해에 한정된다.", "위임계약을 불리한 시기에 해지하면 위임이 해지되었다는 사실에서 생기는 모든 손해를 배상하여야 한다.", "민법 제689조", "손해배상 범위"),
    spec(26, "상소 조언의무", "패소 판결에 불이익한 계산상 잘못이 있으면 특별한 상소 수권이 없더라도 변호사는 판결 내용과 상소 가능성을 설명하고 조언할 의무가 있다.", "패소 판결이 있어도 특별한 상소 수권이 없으면 변호사는 판결의 계산상 잘못이나 상소 가능성을 설명할 의무가 없다.", "민법 제681조, 관련 판례", "상소 조언"),

    spec(27, "상대방 변호사 존중", "변호사는 수임사건을 처리하면서 상대방을 대리하는 변호사와도 서로 존중하고 예의를 갖추어야 한다.", "변호사는 위임인의 이익을 보호하는 사람이므로 상대방 변호사를 존중하거나 예의를 갖출 필요가 없다.", "변호사법 제24조, 변호사윤리장전 제1조", "상대방 변호사"),
    spec(27, "품위유지", "변호사는 품위를 유지하고 명예를 손상하는 행위를 하지 않아야 한다.", "변호사는 직무 외 사생활에서는 품위와 명예를 고려할 의무가 없다.", "변호사법 제24조", "품위유지"),
    spec(27, "공익직무 수행", "변호사는 국선변호 등 공익에 관한 직무를 위촉받았을 때 공정하고 성실하게 수행하며 이해관계인으로부터 부당한 보수를 받지 않는다.", "변호사는 국선변호 등 공익직무에서도 이해관계인으로부터 별도 보수를 받을 수 있다.", "변호사법 제1조, 변호사윤리장전 제1조", "부당 보수"),
    spec(27, "공공의 이익", "변호사는 공공의 이익을 위하여 봉사하며 법령과 제도의 민주적 개선에 노력하여야 한다.", "변호사의 사명에는 공공의 이익을 위한 봉사나 법령·제도의 개선 노력이 포함되지 않는다.", "변호사법 제1조", "공익과 제도개선"),

    spec(28, "음주운전과 품위유지", "변호사의 음주운전은 형사처벌과 별도로 변호사의 품위유지의무 위반이 될 수 있다.", "변호사가 사적인 모임 후 음주운전으로 적발된 경우 형사처벌은 별론으로 하고 품위유지의무 위반은 아니다.", "변호사법 제24조, 제91조", "음주운전"),
    spec(28, "세금 체납과 품위유지", "고액의 세금을 장기간 체납한 행위는 고의가 없다는 사정만으로 품위유지의무 위반이 당연히 부정되지 않는다.", "고액의 세금을 장기간 체납하였더라도 고의적 체납이 아니면 품위유지의무 위반은 아니다.", "변호사법 제24조, 제91조", "세금체납"),
    spec(28, "접대 명목 금품 요구", "사건 담당 공무원에 대한 접대 명목으로 의뢰인에게 금품을 요구하는 행위는 변호사의 품위유지의무 위반이다.", "사건 담당 공무원에 대한 접대 명목이라도 실제 접대가 이루어지지 않으면 의뢰인에게 금품을 요구해도 품위유지의무 위반이 아니다.", "변호사법 제24조, 제91조", "접대 명목 금품"),
    spec(28, "품위손상 판단기준", "품위손상 여부는 수범자인 평균적인 변호사를 기준으로 판단한다.", "품위손상 여부는 해당 변호사의 개인적 가치관만을 기준으로 판단한다.", "변호사법 제24조, 관련 판례", "평균적 변호사"),

    spec(29, "법조윤리협의회 자료요구", "법조윤리협의회는 징계개시 신청을 위하여 필요한 경우 관계인이나 관계 기관에 자료 제출을 요구할 수 있다.", "법조윤리협의회는 징계개시 신청을 위하여 필요한 경우에도 관계인이나 관계 기관에 자료 제출을 요구할 수 없다.", "변호사법 제88조", "자료제출 요구"),
    spec(29, "재판연구원 제외", "재판연구원으로 근무하다가 퇴직한 변호사는 변호사법상 공직퇴임변호사의 수임자료 제출의무 대상에서 제외된다.", "재판연구원으로 근무하다가 퇴직한 변호사도 변호사법상 공직퇴임변호사의 수임자료 제출의무를 부담한다.", "변호사법 제31조 제3항, 제89조의4", "재판연구원"),
    spec(29, "특정변호사 자료제출", "특정변호사는 윤리협의회가 수임 경위 확인을 위하여 요구한 경우에 사건 목록에 기재된 사건의 수임자료와 처리 결과를 제출한다.", "특정변호사는 소속 지방변호사회가 작성한 사건 목록에 기재된 사건의 수임자료와 처리 결과를 별도 요구 없이 항상 법조윤리협의회에 제출하여야 한다.", "변호사법 제89조의5", "요구에 따른 제출"),
    spec(29, "업무내역서와 징계개시", "법조윤리협의회 위원장은 퇴직공직자의 업무내역서에서 징계사유를 발견하면 대한변호사협회의 장에게 징계개시를 신청할 수 있다.", "법조윤리협의회 위원장은 퇴직공직자의 업무내역서에서 징계사유를 발견하여도 징계개시 신청을 할 수 없다.", "변호사법 제89조의6", "징계개시 신청"),

    spec(30, "공직퇴임변호사 수임제한 기준기간", "공직퇴임변호사의 수임제한은 퇴직 전 1년부터 퇴직할 때까지 근무한 국가기관이 처리하는 사건을 기준으로 한다.", "공직퇴임변호사의 수임제한은 과거에 한 번이라도 근무한 모든 국가기관이 처리하는 사건에 적용된다.", "변호사법 제31조 제3항", "퇴직 전 1년"),
    spec(30, "겸직 법인 사건 수임", "변호사가 감사로 겸직하고 있는 법인으로부터 법률사건을 수임하는 것이 언제나 금지되는 것은 아니다.", "변호사가 감사로 겸직하고 있는 법인으로부터 법률사건을 수임하는 것은 언제나 금지된다.", "변호사법 제38조, 제31조", "감사 겸직"),
    spec(30, "위원 직무 관련 사건", "공무원으로 의제되는 위원회 위원이 의결에 참여한 사건과 관련된 사건은 법무법인 수임제한이 문제될 수 있다.", "공무원으로 의제되는 위원회 위원이 의결에 참여한 사건도 담당변호사에서 배제하면 법무법인은 언제나 수임할 수 있다.", "변호사법 제31조", "위원 직무 관련"),
    spec(30, "공직퇴임 자료 제출", "공직퇴임변호사의 수임자료는 퇴직일부터 2년 동안 대통령령으로 정하는 기간마다 소속 지방변호사회에 제출하는 구조이다.", "공직퇴임변호사가 속한 법무법인은 매년 1월 말까지 그 변호사의 전년도 업무내역서를 작성하여 주사무소 지방변호사회에 제출하여야 한다.", "변호사법 제89조의4", "제출 구조"),

    spec(31, "대응 법원·검찰청", "공직퇴임변호사의 수임제한에서 법원과 그에 대응하여 설치된 검찰청은 동일한 국가기관으로 본다.", "공직퇴임변호사의 수임제한에서 법원과 그에 대응하는 검찰청은 서로 다른 국가기관으로 보아 언제나 제한이 없다.", "변호사법 제31조 제3항", "대응 국가기관"),
    spec(31, "경찰관서와 검찰청", "경찰관서에서 퇴직한 변호사가 속한 법무법인이 그와 다른 검찰청 처리 사건을 수임하는 것이 언제나 금지되는 것은 아니다.", "경찰관서에서 퇴직한 변호사가 속한 법무법인은 퇴직 후 1년 동안 같은 지역 검찰청 사건을 모두 수임할 수 없다.", "변호사법 제31조 제3항", "경찰과 검찰"),
    spec(31, "지방검찰청과 고등법원", "지방검찰청에서 퇴직한 변호사가 퇴직 전 근무기관과 동일 국가기관으로 보지 않는 고등법원 처리 사건을 수임하는 것은 제한되지 않을 수 있다.", "지방검찰청에서 퇴직한 변호사는 퇴직 후 1년 동안 같은 지역의 고등법원 사건도 언제나 수임할 수 없다.", "변호사법 제31조 제3항", "검찰청과 고등법원"),
    spec(31, "본청과 지청", "지방검찰청 본청 근무 경력만으로 그 지청이 처리하는 사건까지 항상 공직퇴임변호사 수임제한 대상이 되는 것은 아니다.", "지방검찰청 본청에서 근무한 변호사는 퇴직 후 1년 동안 그 지방검찰청 지청이 처리하는 사건을 모두 수임할 수 없다.", "변호사법 제31조 제3항, 변호사법 시행령 제7조의2", "본청과 지청"),

    spec(32, "세무사 자격 자동부여", "변호사에게 세무사 자격을 더 이상 자동 부여하지 않는 구 세무사법 조항이 곧바로 직업의 자유를 침해한다고 볼 수 없다.", "변호사에게 세무사 자격을 더 이상 자동 부여하지 않는 구 세무사법 조항은 변호사의 직업의 자유를 침해한다.", "관련 헌법재판소 결정", "세무사 자격"),
    spec(32, "공인노무사의 상담 범위", "공인노무사가 의뢰인에게 노동관계 법령을 넘어 수사절차에 적용되는 형사소송법 내용까지 상담하는 것은 특별한 사정이 없는 한 위법하다.", "공인노무사는 노동사건과 관련되기만 하면 수사절차에 적용되는 형사소송법 내용까지 자유롭게 상담할 수 있다.", "변호사법 제3조, 관련 판례", "공인노무사 업무범위"),
    spec(32, "손해사정사 업무범위", "손해사정사는 보수를 받고 피해자와 보험회사 사이의 합의를 유도하는 법률사무를 수행할 수 없다.", "손해사정사는 보험금 산정 업무를 전문으로 하므로 보수를 받고 피해자와 보험회사 사이의 합의를 유도할 수 있다.", "변호사법 제3조, 관련 판례", "손해사정사 합의 유도"),
    spec(32, "변호사와 부동산 중개", "변호사도 중개사무소 개설등록 없이 부동산 중개행위를 할 수는 없다.", "변호사의 직무 범위는 일반 법률사무 전반이므로 중개사무소 개설등록 없이 부동산 중개행위를 할 수 있다.", "변호사법 제3조, 공인중개사법 관련 판례", "부동산 중개"),

    spec(33, "연고관계 선전", "변호사가 재판부와의 연고관계를 선전하여 그 재판부가 담당하는 사건을 수임하면 형사처벌 대상이 될 수 있다.", "변호사가 재판부와의 연고관계를 선전하여 사건을 수임하여도 형사처벌 대상은 아니고 과태료 부과 대상일 뿐이다.", "변호사법 제30조, 제109조, 제117조", "형사처벌과 과태료"),
    spec(33, "항소권 상실 손해", "소송대리 변호사의 선관주의의무 위반으로 항소권이 소멸한 경우 통상손해는 항소를 통해 얻을 수 있었던 금원 상당으로 볼 수 있다.", "변호사의 선관주의의무 위반으로 항소권이 소멸해도 의뢰인이 항소로 얻을 수 있었던 금원은 손해로 볼 수 없다.", "민법 제681조, 관련 판례", "항소권 상실"),
    spec(33, "착수금 반환 범위", "위임사무 처리 도중 변호사의 귀책사유로 계약이 종료되어도 이미 처리한 사무의 정도 등을 고려한 상당 보수와 비용은 착수금에서 공제될 수 있다.", "위임사무 처리 도중 변호사의 귀책사유로 계약이 종료되면 이미 처리한 사무와 무관하게 착수금 전액을 반환하여야 한다.", "민법 제686조, 관련 판례", "상당 보수 공제"),
    spec(33, "위임사무 범위", "소송대리 변호사의 구체적인 위임사무 범위는 변호사와 의뢰인 사이의 위임계약 내용에 따라 정하여진다.", "소송대리 변호사의 위임사무 범위는 위임계약 내용과 무관하게 항상 모든 관련 법률문제를 포함한다.", "민법 제681조, 관련 판례", "위임계약 내용"),

    spec(34, "법무법인과 공무원 취급 사건", "법무법인은 구성원이나 소속 변호사가 공무원·조정위원·중재인으로 직무상 취급하거나 취급하게 된 사건을 수임할 수 없다.", "법무법인은 특정 변호사가 공무원으로 직무상 취급한 사건도 그 변호사만 배제하면 언제나 수임할 수 있다.", "변호사법 제31조, 제57조", "공무원 취급 사건"),
    spec(34, "정관 인증 사건", "법무법인은 상법상 정관을 인증한 사건의 소송대리를 할 수 없다.", "법무법인은 상법상 정관을 인증한 사건이라도 소송대리를 할 수 있다.", "변호사법 제31조, 제57조", "정관 인증"),
    spec(34, "특정 변호사의 친족관계", "상대방 또는 상대방 대리인과의 친족관계가 특정 변호사에게만 있고 그 변호사가 관여하지 않으며 사건 처리에 영향이 없다고 볼 합리적 사유가 있으면 법무법인의 수임이 허용될 수 있다.", "상대방 또는 상대방 대리인과의 친족관계가 특정 변호사에게만 있어도 의뢰인이 동의하지 않으면 법무법인은 언제나 사건을 수임할 수 없다.", "변호사법 제31조, 제57조", "친족관계 차단"),
    spec(34, "의사록 인증 사건", "법무법인은 법인의 등기 절차에 첨부되는 의사록을 인증한 사건의 소송대리를 할 수 없다.", "법무법인은 법인의 등기 절차에 첨부되는 의사록을 인증한 사건의 소송대리를 할 수 있다.", "변호사법 제31조, 제57조", "의사록 인증"),

    spec(35, "국선변호인 취소와 항소이유서 기간", "필요적 변호 사건에서 국선변호인과 피고인에게 소송기록접수통지가 된 뒤 국선변호인 선정이 취소되어도 항소이유서 제출기간은 그 통지를 받은 날부터 계산한다.", "필요적 변호 사건에서 국선변호인 선정이 취소되면 항소이유서 제출기간은 새 사선변호인 선임일부터 새로 진행한다.", "형사소송법, 관련 판례", "소송기록접수통지"),
    spec(35, "국선에서 사선 전환", "구속피고인의 국선변호인이 피고인의 요청에 따라 수임료를 받고 사선변호인으로 전환하는 것이 곧바로 변호사윤리에 위반되는 것은 아니다.", "국선변호인은 피고인의 요청이 있어도 수임료를 받고 사선변호인으로 전환할 수 없다.", "변호사윤리 관련 판례", "사선 전환"),
    spec(35, "사임한 국선변호인과 항소이유서", "사임한 국선변호인이 항소이유서를 제출하지 않았고 피고인에게 귀책사유가 특별히 밝혀지지 않으면 항소법원은 새 국선변호인에게 항소이유서를 제출하도록 하여야 한다.", "사임한 국선변호인이 항소이유서를 제출하지 않으면 피고인에게 귀책사유가 없어도 항소법원은 곧바로 항소를 기각할 수 있다.", "형사소송법, 관련 판례", "새 국선변호인"),
    spec(35, "사임신청과 비밀유지", "국선변호인이 사임허가신청서에 피고인의 위법한 요구를 지나치게 상세히 적어 제출하면 비밀유지의무 위반이 될 수 있다.", "국선변호인이 사임허가신청서에 피고인의 위법한 요구를 지나치게 상세히 적어도 비밀유지의무 위반은 아니다.", "변호사법 제26조", "사임 사유 상세기재"),

